UPDATE phpbb_posts SET post_text = 'quote:Originally posted by Jackson Dane What settings did you use yayoism? I can\'t stand the ultra-large font. I just want it back to the way it is in 1.5 [] Here is what I\'ve setup: // //////////////////////// FONTS ///////////////////////////// // // describes all the fonts Fonts { // fonts are used in order that they are listed // fonts listed later in the order will only be used if they fulfill a range not already filled // if a font fails to load then the subsequent fonts will replace "Default" { "1" { "name" "Tahoma" "tall" "14" "weight" "0" } } "DefaultUnderline" { "1" { "name" "Tahoma" "tall" "14" "weight" "0" "underline" "1" } } "DefaultSmall" { "1" { "name" "Tahoma" "tall" "14" "weight" "0" } } "DefaultVerySmall" { "1" { "name" "Tahoma" "tall" "14" "weight" "0" } } "MenuLarge" { "1" { "name" "Tahoma" "tall" "14" "weight" "1000" "antialias" "1" } "2" { "name" "Tahoma" "tall" "14" "weight" "800" "antialias" "1" } } // this is the symbol font "Marlett" { "1" { "name" "Marlett" "tall" "14" "weight" "0" "symbol" "1" } } "EngineFont" { "1" { "name" "Verdana Bold" "tall" "14" "weight" "0" "yres" "480 599" "dropshadow" "1" } "2" { "name" "Verdana Bold" "tall" "14" "weight" "0" "yres" "600 767" "dropshadow" "1" } "3" { "name" "Verdana Bold" "tall" "14" "weight" "0" "yres" "768 1023" "dropshadow" "1" } "4" { "name" "Verdana Bold" "tall" "14" "weight" "0" "yres" "1024 1199" "dropshadow" "1" } "5" { "name" "Verdana Bold" "tall" "14" "weight" "0" "yres" "1200 6000" "dropshadow" "1" } "6" { "name" "Verdana" "tall" "14" "weight" "600" "dropshadow" "1" } "7" { "name" "Arial" "tall" "14" "weight" "800" "dropshadow" "1" } } "CreditsFont" { "1" { "name" "Trebuchet MS" "tall" "14" "weight" "600" "antialias" "1" } "2" { "name" "Arial" "tall" "14" "weight" "600" "dropshadow" "1" } } "Legacy_CreditsFont" // Added to accomodate 3rd party server plugins, etc. This version should not scale. { "1" { "name" "Trebuchet MS" "tall" "20" "weight" "700" "antialias" "1" "yres" "1 10000" } "2" { "name" "Arial" "tall" "20" "weight" "600" "dropshadow" "1" } } }' WHERE post_id = 91105 AND is_historical = 1;
