UPDATE phpbb_posts SET post_subject = 'Re: Running a server with a router and playing on router with a 2nd machine', post_text = '[Opened ports for computer A (HLDS computer) 27010 27016 27040 Opened ports for computer B (Steam CS computer) 27000-27009 27011-27015 27030-27039 1200 27056 (this port is for steam ip address verification if open it will allow steam to see the ip address of the Ethernet card, not the router.) To hosting the HLDS, you have to open this ports 27010,27016,27040 or Ports forwarding this three ports to lan IP. on Steam Client side is that just open the ports one the router 27000-27009 27011-27015, 27030-27039, 1200, 27056' WHERE post_id = 160915 AND is_historical = 1;
