UPDATE phpbb_posts SET post_subject = 'FIX for missing chat text', post_text = 'If you don\'t see chat text and other text is missing in DOD 1.1, it\'s probably because you\'re running a custom Steam skin. Go back to the default skin, restart Steam, and you should see chat messages.' WHERE post_id = 223715 AND is_historical = 1;
