UPDATE phpbb_posts SET post_text = 'You can use almost any distro that you want, Debian is a good one, I personally use Gentoo. Check out Distrowatch to compare different distros. http://www.distrowatch.com (http://www.distrowatch.com)' WHERE post_id = 490866 AND is_historical = 1;
