UPDATE phpbb_posts SET post_text = 'Don\'t know if this has been posted elsewhere, but here\'s a good demo of the 1) Torso-directional bug 2) Hitbox outside the model bug http://www.fakelabs.net/cs-model-hitboxes.rar (http://www.fakelabs.net/cs-model-hitboxes.rar) (1.42MB)' WHERE post_id = 591673 AND is_historical = 1;
