UPDATE phpbb_posts SET post_text = 'quote:Originally posted by nomex45 or noob toob. \'Noob Toob\' is another way of saying it. \'n00b st1ck\' was meant to rhyme with \'boom stick\' (a type of shotgun) rather than have each word rhyme with the opposite.' WHERE post_id = 577587 AND is_historical = 1;
UPDATE phpbb_posts SET post_text = 'It also isnt nearly as good as a p90 in every situation its supposedly \'good\' in.' WHERE post_id = 577617 AND is_historical = 1;
